/* ==========================================================================
   RESET & CSS VARIABLES
   ========================================================================== */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
    font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    -webkit-font-smoothing: antialiased;
}

:root {
    /* Theme V1 (Default - Classic Swiss Flat) */
    --bg-body: #f1f5f9;
    --bg-card: #ffffff;
    --bg-sidebar: #0f172a;
    --bg-header: #ffffff;
    --bg-hover: #e2e8f0;
    --bg-accent-light: #eff6ff;

    --text-primary: #0f172a;
    --text-secondary: #475569;
    --text-muted: #94a3b8;
    --text-sidebar: #cbd5e1;
    --text-sidebar-active: #ffffff;

    --border-color: #e2e8f0;
    --border-width: 1px;
    --border-radius: 8px;
    --button-radius: 6px;

    --color-primary: #2563eb;
    --color-primary-hover: #1d4ed8;
    --color-success: #16a34a;
    --color-warning: #d97706;

/* --------------------------------------------------------------------------
   THEME VARIATIONS (6 Distinct Flat Aesthetics)
   -------------------------------------------------------------------------- */

/* V1: Classic Swiss Flat */
body.theme-v1 {
    --bg-body: #f1f5f9;
    --bg-card: #ffffff;
    --bg-sidebar: #0f172a;
    --bg-header: #ffffff;
    --bg-hover: #f1f5f9;
    --bg-accent-light: #eff6ff;
    --text-primary: #0f172a;
    --text-secondary: #475569;
    --border-color: #e2e8f0;
    --color-primary: #2563eb;
    --color-primary-hover: #1d4ed8;
    --color-success: #16a34a;
    --color-danger: #dc2626;
    --border-radius: 8px;
    --box-shadow: none;
}

/* V2: Soft Pastel Flat */
body.theme-v2 {
    --bg-body: #faf5ff;
    --bg-card: #ffffff;
    --bg-sidebar: #4c1d95;
    --bg-header: #ffffff;
    --bg-hover: #f3e8ff;
    --bg-accent-light: #f5f3ff;
    --text-primary: #3b0764;
    --text-secondary: #6b21a8;
    --text-muted: #a855f7;
    --text-sidebar: #e9d5ff;

/* ==========================================================================
   TOP-RIGHT THEME SWITCHER
   ========================================================================== */
.version-switcher {
    position: fixed;
    top: 14px;
    right: 20px;
    z-index: 9999;
    display: flex;
    align-items: center;
    gap: 6px;
    background: var(--bg-card);
    border: var(--border-width) solid var(--border-color);
    padding: 6px 12px;
    border-radius: 30px;
    box-shadow: var(--box-shadow);
}

.version-switcher label {
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    color: var(--text-secondary);
    margin-right: 4px;
}

.version-btn {
    width: 28px;
    height: 28px;
    border-radius: 50%;
    border: 2px solid transparent;
    font-weight: 700;
    font-size: 0.75rem;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
    color: #fff;

/* ==========================================================================
   SIDEBAR COMPONENT
   ========================================================================== */
.sidebar {
    width: 260px;
    background-color: var(--bg-sidebar);
    color: var(--text-sidebar);
    display: flex;
    flex-direction: column;
    flex-shrink: 0;
    transition: all 0.3s ease;
    border-right: var(--border-width) solid var(--border-color);
}

.sidebar-header {
    height: 64px;
    display: flex;
    align-items: center;
    padding: 0 20px;
    gap: 12px;
    border-bottom: 1px solid rgba(255,255,255,0.1);
}

.sidebar-logo-icon {
    width: 32px;
    height: 32px;
    background-color: var(--color-primary);
    color: #ffffff;
    border-radius: var(--button-radius);
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 800;
    font-size: 1.1rem;
    font-family: 'Space Grotesk', sans-serif;
}

